bool stratum_subscribe(struct pool *pool) {
    json_t *req, *resp;
    char *sid, *nonce, *nonce2;
    int rc;
    bool success = false;

    req = json_object();
    json_object_set_new(req, "method", json_string("mining.subscribe"));
    json_object_set_new(req, "params", json_array());
    json_object_set_new(req, "id", json_integer(1));

    resp = rpc_call(pool, req, &rc);
    if (!resp) {
        applog(LOG_ERR, "Stratum subscribe failed for pool %d", pool->pool_no);
        goto out;
    }

    if (rc != 200 || !json_is_array(resp)) {
        applog(LOG_ERR, "Invalid Stratum response for pool %d", pool->pool_no);
        goto out;
    }

    json_t *result = json_array_get(resp, 0);
    if (!json_is_array(result)) {
        applog(LOG_ERR, "Malformed subscription result for pool %d", pool->pool_no);
        goto out;
    }

    sid = strdup(json_string_value(json_array_get(result, 1)));
    nonce = strdup(json_string_value(json_array_get(result, 2)));
    nonce2 = strdup(json_string_value(json_array_get(result, 3)));

    if (!sid || !nonce || !nonce2) {
        applog(LOG_ERR, "Missing session data in Stratum response for pool %d", pool->pool_no);
        goto out;
    }

    free(pool->session_id);
    pool->session_id = sid;
    free(pool->nonce);
    pool->nonce = nonce;
    free(pool->nonce2);
    pool->nonce2 = nonce2;

    success = true;

out:
    if (resp)
        json_decref(resp);
    if (req)
        json_decref(req);

    return success;
}

bool stratum_init(struct pool *pool) {
    int retry = 0;
    json_t *resp = NULL;
    char *session_id = NULL;
    char *extradata = NULL;
    size_t extradata_len = 0;
    bool ret = false;

    while (retry < 2) {
        json_t *req = json_object();
        if (!req)
            goto out;

        json_object_set_new(req, "method", json_string("mining.subscribe"));
        json_object_set_new(req, "params", json_array());
        json_object_set_new(req, "id", json_integer(1));

        if (!stratum_send_recv(req, &resp)) {
            applog(LOG_ERR, "Failed to send/recv subscription request to pool %s", pool->rpc_url);
            json_decref(req);
            retry++;
            continue;
        }

        json_decref(req);

        if (!resp || !json_is_object(resp)) {
            applog(LOG_ERR, "Invalid response from pool %s", pool->rpc_url);
            goto out;
        }

        json_t *error = json_object_get(resp, "error");
        if (error && !json_is_null(error)) {
            applog(LOG_ERR, "Subscription error from pool %s: %s", pool->rpc_url, json_dumps(error, 0));
            goto out;
        }

        json_t *result = json_object_get(resp, "result");
        if (!result || !json_is_array(result) || json_array_size(result) < 2) {
            applog(LOG_ERR, "Invalid subscription result from pool %s", pool->rpc_url);
            goto out;
        }

        json_t *session = json_array_get(result, 0);
        if (!session || !json_is_string(session)) {
            applog(LOG_ERR, "Missing or invalid session ID from pool %s", pool->rpc_url);
            goto out;
        }

        session_id = strdup(json_string_value(session));
        if (!session_id) {
            applog(LOG_ERR, "Failed to allocate session ID for pool %s", pool->rpc_url);
            goto out;
        }

        json_t *extradata_json = json_array_get(result, 1);
        if (!extradata_json || !json_is_string(extradata_json)) {
            applog(LOG_ERR, "Missing or invalid extradata from pool %s", pool->rpc_url);
            goto out;
        }

        extradata = strdup(json_string_value(extradata_json));
        extradata_len = strlen(extradata);
        if (!extradata) {
            applog(LOG_ERR, "Failed to allocate extradata for pool %s", pool->rpc_url);
            goto out;
        }

        free(pool->session_id);
        pool->session_id = session_id;
        free(pool->extradata);
        pool->extradata = extradata;
        pool->extradata_len = extradata_len;

        ret = true;
        break;
    }

out:
    if (resp)
        json_decref(resp);
    return ret;
}

bool stratum_init_connection(struct pool *pool) {
    json_t *subscription_req, *resp, *resp_id, *result;
    char *json_req;
    bool retry = false;

    if (!pool)
        return false;

    while (1) {
        subscription_req = json_object();
        if (!subscription_req)
            return false;

        json_object_set_new(subscription_req, "id", json_integer(1));
        json_object_set_new(subscription_req, "method", json_string("mining.subscribe"));
        json_object_set_new(subscription_req, "params", json_array());

        json_req = json_dumps(subscription_req, JSON_COMPACT);
        if (!json_req) {
            json_decref(subscription_req);
            return false;
        }

        if (!stratum_send(pool, json_req)) {
            free(json_req);
            json_decref(subscription_req);
            return false;
        }
        free(json_req);
        json_decref(subscription_req);

        resp = stratum_recv(pool);
        if (!resp)
            return false;

        if (!json_is_object(resp)) {
            json_decref(resp);
            return false;
        }

        resp_id = json_object_get(resp, "id");
        if (!json_is_integer(resp_id) || json_integer_value(resp_id) != 1) {
            json_decref(resp);
            return false;
        }

        result = json_object_get(resp, "result");
        if (!json_is_array(result) || json_array_size(result) < 2) {
            json_decref(resp);
            return false;
        }

        pool->session_id = json_string_value(json_array_get(result, 1));
        if (!pool->session_id) {
            json_decref(resp);
            return false;
        }

        pool->extranonce = json_string_value(json_array_get(result, 0));
        if (!pool->extranonce) {
            json_decref(resp);
            return false;
        }

        json_decref(resp);
        return true;
    }

    return false;
}

bool stratum_init(struct pool *pool) {
    json_t *subscription_req, *resp;
    char *sid = NULL, *nonce = NULL;
    bool ret = false;
    int retry = 0;

    do {
        if (retry)
            pool->session_id[0] = '\0';

        subscription_req = json_object();
        json_object_set_new(subscription_req, "method", json_string("mining.subscribe"));
        json_object_set_new(subscription_req, "params", json_array());
        json_object_set_new(subscription_req, "id", json_integer(1));

        if (!stratum_send_recv(pool, subscription_req, &resp)) {
            applog(LOG_DEBUG, "Stratum subscription request failed");
            json_decref(subscription_req);
            continue;
        }

        json_decref(subscription_req);

        if (!json_is_array(resp)) {
            applog(LOG_DEBUG, "Stratum response is not an array");
            json_decref(resp);
            continue;
        }

        json_t *result = json_array_get(resp, 1);
        if (!json_is_array(result)) {
            applog(LOG_DEBUG, "Stratum response result is not an array");
            json_decref(resp);
            continue;
        }

        sid = strdup(json_string_value(json_array_get(result, 0)));
        if (!sid) {
            applog(LOG_DEBUG, "Failed to extract session ID from Stratum response");
            json_decref(resp);
            continue;
        }

        nonce = strdup(json_string_value(json_array_get(result, 1)));
        if (!nonce) {
            applog(LOG_DEBUG, "Failed to extract nonce from Stratum response");
            free(sid);
            json_decref(resp);
            continue;
        }

        strcpy(pool->session_id, sid);
        strcpy(pool->nonce, nonce);

        free(sid);
        free(nonce);
        json_decref(resp);

        ret = true;
        break;
    } while (retry++ < 1);

    return ret;
}

bool stratum_init(struct pool *pool) {
    json_t *req, *resp;
    char *sid = NULL, *nonce = NULL;
    int retry = 0;
    bool ret = false;

    while (retry++ < 2) {
        req = json_object();
        json_object_set_new(req, "id", json_integer(1));
        json_object_set_new(req, "method", json_string("mining.subscribe"));
        json_object_set_new(req, "params", json_array());

        if (!stratum_send_recv(pool, req, &resp)) {
            applog(LOG_ERR, "Stratum subscribe failed for %s", pool->rpc_url);
            continue;
        }

        if (!json_is_array(resp)) {
            applog(LOG_ERR, "Stratum subscribe response is not an array");
            json_decref(resp);
            continue;
        }

        json_t *result = json_array_get(resp, 0);
        if (!json_is_array(result)) {
            applog(LOG_ERR, "Stratum subscribe result is not an array");
            json_decref(resp);
            continue;
        }

        json_t *session_id_item = json_array_get(result, 0);
        if (json_is_string(session_id_item)) {
            sid = strdup(json_string_value(session_id_item));
        }

        json_t *nonce_item = json_array_get(result, 1);
        if (json_is_string(nonce_item)) {
            nonce = strdup(json_string_value(nonce_item));
        }

        if (!sid || !nonce) {
            applog(LOG_ERR, "Stratum subscribe response missing session ID or nonce");
            free(sid);
            free(nonce);
            json_decref(resp);
            continue;
        }

        if (pool->session_id)
            free(pool->session_id);
        pool->session_id = sid;

        if (pool->nonce)
            free(pool->nonce);
        pool->nonce = nonce;

        applog(LOG_INFO, "Stratum session initiated for pool %s", pool->rpc_url);
        ret = true;
        json_decref(resp);
        break;
    }

    if (!ret)
        applog(LOG_ERR, "Failed to initiate Stratum session for pool %s", pool->rpc_url);

    return ret;
}
